/* ===== v2 design system additions ===== */
const DEV2=['Foundations','Components','Patterns & flows','Inventory & handoff','Update checklist (A1–B9)'];
V.design=()=>{const tab=UI.dtab||0;return `<div class="stack-lg"><div class="row between wrap-r"><div><h1>${t('ApnaTown design system')}</h1><p class="t2">${t('Tokens, components, patterns and the screen inventory. Everything here is rendered with the live app styles.')}</p></div><button class="btn g sm" data-act="theme" data-v="${(document.documentElement.dataset.theme==='dark')?'light':'dark'}">${ic('moon',16)} ${t('Toggle dark mode')}</button></div><div class="tabs">${DEV2.map((l,i)=>`<button class="${tab===i?'on':''}" data-act="dtab" data-v="${i}">${t(l)}</button>`).join('')}</div>${[dsFound,dsComp2,dsPat2,dsInv2,dsCheck][tab]()}</div>`};
function dsComp2(){const sh=(l,h)=>`<div class="card pad stack"><h3>${l}</h3>${h}</div>`;const a1=D().admins[0],oo=UI.xad.open;UI.xad.open={[a1.id]:true};const exp=adCard(a1);UI.xad.open={};const col=adCard(D().admins[1]);UI.xad.open=oo;
 const cfg={label:'Send to customers of',placeholder:'Search customers, shops or service providers',value:'b1',recent:['b4'],items:[...D().users.map(u=>({id:u.id,label:u.name,sub:'+91 '+u.phone,group:'Customers'})),...D().biz.slice(0,4).map(b=>({id:b.id,label:b.name.en,sub:catName(b.cat),group:'Shops'}))],onPick:()=>toast(t('Picked'))};
 const m=biz('b4').media[0];
 return dsComp()+`<div class="card pad" style="background:var(--primary-soft)"><b>${t('New and changed in this update')}</b></div>
 ${H2('Tabbed chart card (A1)')}${chartCard()}
 ${H2('Collapsible admin card + search/filter bar (A3)')}${sh('Collapsed and expanded',`<div class="searchbar">${ic('search',18)}<input placeholder="${t('Search name, phone or email')}" aria-label="Search"></div><div class="row wrap-r" style="gap:6px"><span class="rchip">Padrauna <b>${ic('x',14)}</b></span><span class="rchip">Support <b>${ic('x',14)}</b></span><button class="btn t sm">${t('Clear all')}</button></div><div class="grid g2"><div>${col}</div><div>${exp}</div></div>`)}
 ${H2('Confirmation dialog (A3, A4, A5)')}${sh('Names who is affected, the impact, and uses text labels',`<div class="row wrap-r"><button class="btn d sm" data-act="dsDeact">Deactivate admin</button><button class="btn g sm" data-act="dsDelRole">Delete role with admins</button></div>`)}
 ${H2('Searchable dropdown (A6, A7)')}${sh('Type to filter, recent items, grouped, keyboard: ↑ ↓ Enter Esc',comboHtml('dsc',cfg))}
 ${H2('Role editor, scope selector')}${sh('Unsaved indicator, matrix, before/after summary',`<div class="row between"><b>Support</b><span class="badge warn">● ${t('Unsaved changes')}</span></div><div class="perm" style="grid-template-columns:1.6fr repeat(5,1fr);min-width:0"><div class="h n">${t('Module')}</div>${RACTS.map(a=>`<div class="h">${t(a[1])}</div>`).join('')}${MODS.slice(0,3).map(([k,lb])=>`<div class="n">${t(lb)}</div>${RACTS.map(([c])=>`<div><input type="checkbox" ${(ROLE_MATRIX.Support[k]||'').includes(c)?'checked':''} aria-label="${lb} ${c}" style="width:20px;height:20px"></div>`).join('')}`).join('')}</div>${segBtn('noop','city',[['all','Overall'],['city','City-wise'],['zone','Zone-wise']])}`)}
 ${H2('City detail view + live map city filter')}${sh('Zone polygon editor, zone list, assigned admins',`<div class="row wrap-r"><a class="btn p sm" href="#xcity-padrauna" data-act="asRole" data-role="super">${t('Open city detail (Padrauna)')}</a><a class="btn g sm" href="#alive" data-act="asRole" data-role="super">${t('Open live map')}</a></div>`)}
 ${H2('Responsive shop card')}${sh('Image on top, details at the bottom. 1 / 2 / 3–4 columns',`<div class="shopgrid">${D().biz.slice(0,4).map(shopCard).join('')}</div>`)}
 ${H2('Media carousel with video, heart, full-screen viewer')}${sh('Thumbnails with play badge. Viewer: prev/next, swipe, ← →, counter, zoom, heart',`<div class="thumbs">${prod('p45').media.map((x,i)=>`<button class="${i?'':'on'}" aria-label="media ${i+1}">${pmArt(x,'')}${x.t!=='img'?`<span class="pb">${ic('play',12)}</span>`:''}</button>`).join('')}</div><div class="row wrap-r"><button class="btn p sm" data-act="openViewer" data-id="p45" data-i="3">${t('Open full-screen viewer')}</button>${heartBtn('ds|heart',{kind:'photo',owner:'b4',title:'Demo'})}<span class="small muted">${t('Heart: animates; reduced motion shows a check instead')}</span></div>`)}
 ${H2('Embed tag picker + tagged items under a video')}${sh('“In this video” chips and cards with Add to cart / View service',`${tagCards(m)}<button class="btn o sm" data-act="dsTag">${t('Open tag picker')}</button>`)}
 ${H2('Per-tab filter sheets (Explore)')}${sh('Products, Shops and Services each keep their own filters',`<div class="row wrap-r"><button class="btn g sm" data-act="dsFilter" data-tab="p">${t('Products filters')}</button><button class="btn g sm" data-act="dsFilter" data-tab="b">${t('Shops filters')}</button><button class="btn g sm" data-act="dsFilter" data-tab="s">${t('Services filters')}</button></div>`)}`}
A.dsDeact=()=>A.adSwitch({dataset:{id:'ad2'}});A.dsDelRole=()=>A.rlDel({dataset:{id:'rl1'}});
A.dsFilter=el=>{UI.exTab=el.dataset.tab;A.exFilters()};A.dsTag=()=>{const b=biz('b4');S.__sv=S.vend.bid;S.vend.bid='b4';const r=S.role;S.role='vendor';A.tagPick({dataset:{i:0}});S.role=r;S.vend.bid=S.__sv};
const FLOWS2=[['Explore redirects: “View all” → Explore',[['Home','home'],['View all products','home'],['Explore ▸ Products (Featured)','explore'],['View all businesses','home'],['Explore ▸ Shops (Featured)','explore'],['View all shops','home'],['Explore ▸ Shops (by distance)','explore']]],['Subcategory suggestion → approval',[['Vendor ▸ Products','vproducts'],['Suggest a subcategory','vproducts'],['Admin ▸ Suggestions queue','asubs'],['Approve / Reject / Merge','asubs'],['Vendor notified','vnotif'],['Subcategory in product editor','vprod-new']]],['Admin activate / deactivate',[['Admins & areas','xadmins'],['Open admin card','xadmins'],['Deactivate','xadmins'],['Confirm dialog (impact)','xadmins'],['Success toast + status badge','xadmins']]],['Video tagging → add to cart',[['Vendor ▸ Gallery & media','vmedia'],['Paste YouTube / Instagram link','vmedia'],['Tag products','vmedia'],['Customer ▸ Shop ▸ Gallery & Videos','biz-b4'],['Play video','biz-b4'],['Tap tag ▸ Add to cart','cart']]]];
const dsPat2=()=>dsPat().replace(H2('Status models'),`${H2('Update flows (A–B)')}<div class="stack">${FLOWS2.map(([n,steps])=>`<div class="card pad stack"><b>${n}</b><div class="row wrap-r" style="gap:6px">${steps.map(([l,r],i)=>`${i?ic('cr',16):''}<a class="chip" href="#${r}" data-act="flowGo" data-r="${r}">${i+1}. ${l}</a>`).join('')}</div></div>`).join('')}</div>${H2('Status models')}`);
const INV3=[['Super Admin ▸ Overview (tabbed chart)','Super Admin','#xhome','Chart card, Tabs, Select, Tooltip','Graph, Candle, skeleton, empty (non-live city), error'],['Categories (fixed main + subcategories)','Super Admin / Admin','#acats','List, Lock badge, Chips','view-only for Admin, success toast'],['Subcategory suggestions queue (new)','Admin / Super Admin','#asubs','Cards, Dialog, Select','Pending, Approved, Rejected, Merged, empty, duplicate warning'],['Suggest a subcategory (new)','Vendor / Provider','#vproducts · #sproducts (sheet)','Form, Duplicate alert','duplicate, success, notification'],['Admins & areas (collapsible cards)','Super Admin','#xadmins','Collapsible card, Search, Filter sheet, Chips, Confirm dialog','collapsed, expanded, no results, success toast'],['Roles & permissions (edit/delete)','Super Admin','#xroles','Role card, Matrix, Review sheet','unsaved, before/after, blocked delete, system lock'],['Cities (cards) + City detail (new)','Super Admin','#xgeo · #xcity-ID','City card, Polygon editor, Zone list','no zones, draw, edit, enable/disable confirm'],['Live map (city filter)','Admin / Super Admin','#alive','Combobox, Cluster pins, List','All cities, one city, empty, no-permission'],['Communications (scope + combobox + review)','Admin / Super Admin','#acomms','Combobox, Scope selector, Summary sheet','permission-aware scopes, no-permission, success'],['Home: View all buttons + responsive shop card','Customer','#home','Section header button, Shop card','skeleton cover, 1/2/3–4 columns'],['Search (Products · Businesses · Services)','Customer','#search','Tabs, Suggestions','default Products, empty'],['Explore (Products | Shops | Services, per-tab filters)','Customer','#explore','Tabs, Filter sidebar/sheet, Chips','remembered filters, empty, map'],['Unified profile (shop + provider)','Customer','#biz-ID · #svc-ID','Tabs, Sub-tabs, Action bar','products only, services only, both, owner prompt'],['Gallery & Videos (players, tags, hearts)','Customer','#biz-ID ▸ Gallery','Video card, Player sheet, Tag cards, Heart','embed fallback, offline, empty'],['Product detail (media carousel + viewer)','Customer','#prod-ID','Breadcrumb, Carousel, Viewer','video, zoom, keyboard, out-of-stock'],['Saved (Shops | Services | Photos & Videos)','Customer','#bookmarks','Tabs, Filter chips, Heart','guest prompt, empty, remove'],['Vendor/Provider: Services, Gallery & media, Product editor media','Vendor / Provider','#vservices · #vmedia · #vprod-ID (+ s…)','Service form, Link paste, Tag picker, Media sorter','invalid link, preview, success']];
const dsInv2=()=>dsInv().replace(H2('Design tokens (JSON)'),`${H2('Changed and new screens (this update)')}${tbl(['Screen','Role','Route','Components','States covered'],INV3.map(r=>[esc(r[0]),r[1],`<code class="xs">${esc(r[2])}</code>`,esc(r[3]),esc(r[4])]))}${H2('Design tokens (JSON)')}`);
const CHK=[['A1','Overview: tabbed chart (Graph / Candle)','Super Admin ▸ Overview','xhome','super'],['A2','Fixed main categories + subcategory suggestions','Categories · Suggestions queue · Vendor/Provider ▸ Products','acats','super'],['A3','Admins & Areas: collapsible cards, search, filters, confirm','Super Admin ▸ Admins & areas','xadmins','super'],['A4','Roles: edit, delete, duplicate','Super Admin ▸ Roles & permissions','xroles','super'],['A5','Cities & Zones: city cards, city detail, zone editor','Super Admin ▸ Cities & zones','xgeo','super'],['A6','Live Map: city filter, clusters, list','Admin / Super Admin ▸ Live deliveries','alive','super'],['A7','Communications: combobox, scopes, review step','Admin / Super Admin ▸ Communications','acomms','super'],['B1','Home: View all products → Explore (Products, Featured)','Customer ▸ Home','home','customer'],['B2','Home: View all businesses → Explore (Shops, Featured)','Customer ▸ Home','home','customer'],['B3','Home: responsive shop card + View all shops','Customer ▸ Home','home','customer'],['B4','Search order: Products, Businesses, Services','Customer ▸ Search','search','customer'],['B5','Unified Business / Service provider profile','Customer ▸ shop and provider pages','biz-b4','customer'],['B6','Explore: Products | Shops | Services + per-tab filters','Customer ▸ Explore','explore','customer'],['B7','Gallery & Videos: embeds, tagging, hearts','Customer ▸ profile ▸ Gallery · Vendor ▸ Gallery & media','biz-b4','customer'],['B8','Saved: Shops | Services | Photos & Videos','Customer ▸ Account ▸ Saved','bookmarks','customer'],['B9','Product detail: breadcrumbs, media viewer, related View all','Customer ▸ Product (iPhone 16)','prod-p45','customer']];
const dsCheck=()=>`${H2('Checklist: every numbered item and where it is shown')}${tbl(['Item','Requirement','Where','Open'],CHK.map(r=>[`<b>${r[0]}</b>`,esc(r[1]),esc(r[2]),`<a class="btn p sm" href="#${r[3]}" data-act="asRole" data-role="${r[4]}">${t('Open')}</a>`]))}
 ${H2('Which existing screens were changed')}<div class="card pad"><p class="t2">${t('This app is the existing canvas. Its “artboards” are screens (routes). All of these existed and were edited in place: Super Admin Overview, Categories, Admins & Areas, Roles & Permissions, Cities & Zones, Live Map, Communications; Customer Home, Search, Explore, Business and Service provider profiles, Product detail, Saved. No artboard was missing.')}</p></div>
 ${H2('State coverage on changed screens')}${tbl(['State','Where it is built','Not fully covered'],[['Default','All changed screens','—'],['Loading (skeleton)','Chart card, Home shop-card covers, route loading, slow-connection mode','Other new lists use the page skeleton only'],['Empty','Chart (non-live city), no zones, no admins match, no live deliveries, empty Saved, no suggestions, no media, no results','—'],['Error','Chart error (Demo ▸ chart error), page error state, embed fallback','Per-filter error states'],['No permission','Admin without module or scope (Demo ▸ Admin account ▸ Seema), Admin on Super Admin routes, category edits by Admin','—'],['Success','Toasts and sheets after save, send, approve, deactivate','—'],['Hindi','Customer screens and main labels','Many new admin strings still show in English']])}
 ${H2('Assumptions')}<div class="card pad"><ul class="t2" style="margin:0;padding-left:20px"><li>${t('The “existing canvas” is this prototype; artboards map to screens and routes.')}</li><li>${t('Embedded YouTube and Instagram players load only if the hosting page allows frames. If not, the “Open in YouTube / Instagram” fallback is always shown. Seed video IDs are samples.')}</li><li>${t('Candle data is sample data generated from the metric, range and city; there is no real analytics backend.')}</li><li>${t('Only Padrauna is live. Other cities show the empty states. Enable Kasia to see city setup.')}</li><li>${t('Role matrices describe templates. Per-admin permissions are edited separately, and renaming a role updates its admins.')}</li><li>${t('Service price filter uses each provider’s lowest “starts from” price. Brand names are sample data.')}</li><li>${t('Photos are placeholder art; uploads, zoom of real photos and pinch gestures are simulated with emoji images.')}</li><li>${t('Old saved data in your browser is migrated, not erased. “Reset demo data” returns to the fresh seed.')}</li></ul></div>`;
